class Base {
public:
    virtual void foo();
    int a;
};

class Derived : public Base {
public:
    virtual void foo() override;
    float _z;
};

// Implementation notes:
// - Each object of class with virtual functions contains a hidden vptr pointing to the class's vtable.
// - The vtable is an array of function pointers generated by the compiler, representing the virtual functions.
// - During construction, the compiler sets the vptr to the appropriate vtable, considering the current constructor context.
// - Destructors are called in reverse order of inheritance, with vtable adjustments to ensure correct virtual dispatch.
// - Inheritance introduces offsets in memory layout, with derived objects containing base subobjects.
// - Compiler may optimize object layout for cache locality and reduce padding.
// - Virtual calls are resolved at runtime via vtable lookups, with potential inlining opportunities.
// - The object model supports polymorphism, enabling dynamic dispatch based on the actual object type.

// Example:
#include <iostream>

class Base {
public:
    virtual void foo() { std::cout << "Base::foo" << std::endl; }
    int a;
};

class Derived : public Base {
public:
    virtual void foo() override { std::cout << "Derived::foo" << std::endl; }
    float _z;
};
